"""Sandboxed checking of Lean modules against the pinned Mathlib workspace (roadmap W08).

Proof search and proof acceptance are separate. This module is acceptance. It never
reuses anything a search produced: it compiles every module again from source.

A *chain* is an ordered list of modules. Each module is either
  * trusted: generated by Genesis from validated data (definitions, the statements to
    be proved). It may import only the pinned workspace and earlier trusted modules.
  * untrusted: a proof module (from a search, or from a person). It is prescreened
    (imports, forbidden constructs, options) and may import the workspace, trusted
    modules and earlier untrusted modules, i.e. previously accepted library lemmas.

`accept` compiles each module in its own sandbox: no network, a read-only pinned
toolchain and workspace, and only the compiled oleans of its own imports. It then runs
one trusted check stage. That stage
  1. binds each claimed proof to its trusted statement: `theorem genesis_bind_i :
     Spec.stmt := Proof.thm`. The kernel checks this, so a proof of a weaker
     statement is a STATEMENT_MISMATCH;
  2. collects the axioms of every binding. Only propext, Classical.choice and
     Quot.sound are allowed. sorryAx or any declared axiom is DISALLOWED_AXIOM;
  3. extracts every declaration of every module (kind, type fingerprint, the
     constants it uses and their modules, its axioms), for the dependency closure;
  4. replays every untrusted module through the kernel with `leanchecker`.
Results are printed behind per-run nonces, so module output cannot forge them.

Outcome classes (roadmap W08): CHECKED, DISPROVED (a checked proof of the negation),
UNRESOLVED, UNSUPPORTED, ELABORATION_FAILURE, TIMEOUT, CHECKER_FAILURE. Detailed
statuses map onto them with `outcome_class`.
"""
import hashlib
import json
from pathlib import Path
import re
import secrets

from ..common import bytes_hash, digest
from .. import sandbox
from ..verification.lean import ALLOWED_AXIOMS, FORBIDDEN
from ..verification.tools import tool, toolchain_root, ToolUnavailable
from . import workspace as W

POLICY = sandbox.SandboxPolicy(wall_seconds=900, cpu_seconds=840, memory_mib=6144, pids=64, work_mib=512,
                               tmp_mib=64, output_bytes=32 * 1024 * 1024, max_file_mib=256,
                               open_files=16384, address_space_mib=262144)
MODULE_NAME = re.compile(r'^[A-Z][A-Za-z0-9]{0,63}$')
CONST_NAME = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*(\.[A-Za-z_][A-Za-z0-9_]*)*$')
ALLOWED_OPTIONS = frozenset({'maxHeartbeats', 'maxRecDepth', 'synthInstance.maxHeartbeats'})
HEARTBEATS = 400000
OUTCOME_CLASSES = ('CHECKED', 'DISPROVED', 'UNRESOLVED', 'UNSUPPORTED', 'ELABORATION_FAILURE', 'TIMEOUT',
                   'CHECKER_FAILURE')
_CLASS = {'CHECKED': 'CHECKED', 'ELABORATION_ERROR': 'ELABORATION_FAILURE',
          'STATEMENT_MISMATCH': 'ELABORATION_FAILURE', 'KERNEL_REJECTED': 'ELABORATION_FAILURE',
          'DISALLOWED_AXIOM': 'ELABORATION_FAILURE', 'FORBIDDEN_CONSTRUCT': 'ELABORATION_FAILURE',
          'DISALLOWED_IMPORT': 'ELABORATION_FAILURE', 'NOT_ATTEMPTED': 'ELABORATION_FAILURE',
          'TIMEOUT': 'TIMEOUT', 'RESOURCE_LIMIT': 'TIMEOUT', 'CHECKER_ERROR': 'CHECKER_FAILURE'}


def outcome_class(status):
    return _CLASS.get(status, 'CHECKER_FAILURE')


class ChainError(ValueError):
    pass


def imports_of(source):
    return re.findall(r'(?m)^\s*(?:public\s+)?import\s+(\S+)', source)


def prescreen(source, *, permitted):
    """None if an untrusted module may be compiled, else the reason it may not."""
    for pattern in FORBIDDEN:
        m = re.search(pattern, source)
        if m:
            return 'FORBIDDEN_CONSTRUCT', f'forbidden construct {m.group(0).strip()!r}'
    for name in re.findall(r'\bset_option\s+([\w.]+)', source):
        if name not in ALLOWED_OPTIONS:
            return 'FORBIDDEN_CONSTRUCT', f'option {name!r} may not be set'
    if re.search(r'(?m)^\s*module\b', source):
        return 'FORBIDDEN_CONSTRUCT', 'the `module` header is not used by Genesis modules'
    extra = sorted(set(imports_of(source)) - set(permitted))
    if extra:
        return 'DISALLOWED_IMPORT', f'disallowed import {extra}'
    return None


def _env():
    lean = tool('lean')
    ws = W.environment()
    return {'lean': lean['identity'], 'lean_sha256': lean['sha256'], 'toolchain_root': str(toolchain_root()),
            'workspace': {k: ws[k] for k in ('source_identity', 'artifact_identity', 'mathlib_rev', 'import_roots')},
            'olean_root': ws['olean'], 'modules': ws['modules'],
            'allowed_axioms': sorted(ALLOWED_AXIOMS), 'forbidden_patterns_sha256': digest(FORBIDDEN)}


def _run(files, script, env, policy):
    lean_root = str(Path(tool('lean')['path']).parents[1])
    receipt = sandbox.run({**files, 'stage.sh': script.encode()}, ['/bin/sh', '/work/src/stage.sh'], policy,
                          ro_mounts={'/opt/lean': lean_root, W.MOUNT: env['olean_root']},
                          env={'PATH_PREFIX': ['/opt/lean/bin'],
                               'LEAN_PATH': f'/work/src:{W.MOUNT}:/opt/lean/lib/lean'})
    return receipt, receipt.get('_output_bytes', {})


def _stats(receipt):
    return {k: receipt.get(k) for k in ('status', 'exit_code', 'wall_ns', 'cpu_ns', 'peak_memory_bytes')}


def _closure(name, sources, names):
    seen, stack = set(), [name]
    while stack:
        m = stack.pop()
        for i in imports_of(sources[m]):
            if i in names and i not in seen:
                seen.add(i); stack.append(i)
    return seen


def _kept_log(log, limit=6000):
    """The stored module log: every error line first (B20R3-OPEN-3: linter warnings used to push the
    errors out of the last 6000 characters), then the tail of the full log. Diagnostics only; the
    result class is decided from the full log above."""
    if len(log) <= limit:
        return log
    errors = [l for l in log.splitlines() if ': error' in l][:40]
    head = ('\n'.join(errors) + '\n[... earlier output omitted; error lines kept above ...]\n') if errors else ''
    return head + log[-max(1000, limit - len(head)):]


def compile_module(name, source, deps, env, policy=POLICY, heartbeats=HEARTBEATS):
    """Compile one module; `deps` maps flat file names to compiled bytes of its imports."""
    script = (f'set -u\ncd /work/src && lean -D maxHeartbeats={heartbeats} --root=/work/src '
              f'-o /work/out/{name}.olean {name}.lean > /work/out/{name}.log 2>&1 || exit 42\n')
    receipt, out = _run({**deps, f'{name}.lean': source.encode()}, script, env, policy)
    log = out.get(f'{name}.log', b'').decode(errors='replace')
    artifacts = {k: v for k, v in out.items() if k.startswith(name + '.') and not k.endswith('.log')}
    status = receipt['status']
    if status == 'TIMEOUT':
        result = 'TIMEOUT'
    elif status in ('OOM', 'CPU_LIMIT', 'OUTPUT_LIMIT'):
        result = 'RESOURCE_LIMIT'
    elif status in ('SANDBOX_UNAVAILABLE', 'SANDBOX_ERROR', 'LAUNCHER_REFUSED'):
        result = 'CHECKER_ERROR'
    elif receipt.get('exit_code') == 0 and f'{name}.olean' in artifacts:
        result = 'COMPILED'
    elif '(kernel)' in log:
        result = 'KERNEL_REJECTED'
    elif 'heartbeats' in log or 'maximum recursion' in log or 'deterministic timeout' in log:
        result = 'RESOURCE_LIMIT'
    else:
        result = 'ELABORATION_ERROR'
    return {'result': result, 'stats': _stats(receipt), 'log': _kept_log(log), 'artifacts': artifacts,
            'artifact_sha256': {k: bytes_hash(v) for k, v in sorted(artifacts.items())},
            'reason': receipt.get('reason')}


_CHECK_HEADER = r'''import Lean
open Lean Meta
partial def genesisAnon : Expr → Expr
  | .forallE _ t b bi => .forallE `_ (genesisAnon t) (genesisAnon b) bi
  | .lam _ t b bi => .lam `_ (genesisAnon t) (genesisAnon b) bi
  | .letE _ t v b nd => .letE `_ (genesisAnon t) (genesisAnon v) (genesisAnon b) nd
  | .app f a => .app (genesisAnon f) (genesisAnon a)
  | .mdata _ e => genesisAnon e
  | .proj s i e => .proj s i (genesisAnon e)
  | e => e
def genesisKind : ConstantInfo → String
  | .thmInfo _ => "theorem" | .defnInfo _ => "def" | .axiomInfo _ => "axiom" | .opaqueInfo _ => "opaque"
  | .inductInfo _ => "inductive" | .ctorInfo _ => "constructor" | .recInfo _ => "recursor"
  | .quotInfo _ => "quot"
def genesisModuleOf (env : Environment) (n : Name) : String :=
  match env.getModuleIdxFor? n with
  | some i => toString env.header.moduleNames[i.toNat]!
  | none => "_"
partial def genesisSize (fuel : Nat) : Expr → Nat
  | .app f a => if fuel == 0 then 0 else
      let x := genesisSize fuel f; x + genesisSize (fuel - min fuel x) a + 1
  | .lam _ t b _ => if fuel == 0 then 0 else
      let x := genesisSize fuel t; x + genesisSize (fuel - min fuel x) b + 1
  | .forallE _ t b _ => if fuel == 0 then 0 else
      let x := genesisSize fuel t; x + genesisSize (fuel - min fuel x) b + 1
  | .letE _ t v b _ => if fuel == 0 then 0 else
      genesisSize fuel t + genesisSize fuel v + genesisSize fuel b + 1
  | .mdata _ e => genesisSize fuel e
  | .proj _ _ e => genesisSize fuel e + 1
  | _ => 1
partial def genesisTree : Expr → Json
  | .bvar i => Json.arr #["bvar", toJson i]
  | .const n _ => Json.arr #["const", toString n]
  | .app f a => Json.arr #["app", genesisTree f, genesisTree a]
  | .lam _ t b _ => Json.arr #["lam", genesisTree t, genesisTree b]
  | .forallE _ t b _ => Json.arr #["pi", genesisTree t, genesisTree b]
  | .letE _ t v b _ => Json.arr #["let", genesisTree t, genesisTree v, genesisTree b]
  | .lit (.natVal n) => Json.arr #["nat", toJson n]
  | .lit (.strVal s) => Json.arr #["str", s]
  | .sort l => Json.arr #["sort", toString l]
  | .mdata _ e => genesisTree e
  | .proj s i e => Json.arr #["proj", toString s, toJson i, genesisTree e]
  | _ => Json.arr #["other"]
def genesisDump (tag : String) (mods : List Name) (trees : Bool := false) : MetaM Unit := do
  let env ← getEnv
  for m in mods do
    let some idx := env.getModuleIdx? m | IO.println s!"{tag} missing-module {m}"
    let data := env.header.moduleData[idx.toNat]!
    for c in data.constNames do
      let some ci := env.find? c | continue
      let axs ← Lean.collectAxioms c
      let used := ci.getUsedConstantsAsSet.toList.map fun u => Json.arr #[toString u, genesisModuleOf env u]
      let size := match ci.value? (allowOpaque := true) with | some v => genesisSize 1000000 v | none => 0
      let tree := match ci.value?, trees && !c.isInternal with
        | some v, true => genesisTree v
        | _, _ => Json.null
      let j := Json.mkObj [("module", toString m), ("name", toString c), ("kind", genesisKind ci),
        ("internal", Json.bool c.isInternal), ("type", toString (genesisAnon ci.type)),
        ("uses", Json.arr used.toArray), ("axioms", Json.arr (axs.map (Json.str ∘ toString))),
        ("value_nodes", toJson size), ("value_tree", tree)]
      IO.println s!"{tag} decl {j.compress}"
def genesisBind (tag : String) (i : Nat) (bind spec : Name) : MetaM Unit := do
  let env ← getEnv
  match env.find? bind with
  | none => IO.println s!"{tag} bind {i} absent"
  | some ci =>
    let axs ← Lean.collectAxioms bind
    let exact := ci.type == mkConst spec
    IO.println s!"{tag} bind {i} {if exact then "exact" else "other"} {axs.toList}"
'''


def _check_source(imports, bindings, dump, nonce, trees=()):
    """The trusted check file and {line number: binding index} for its binding theorems.
    Modules in `trees` also get the expression tree of every declaration's value (W09)."""
    head = 'import Lean\n' + ''.join(f'import {m}\n' for m in imports)
    out = (head + _CHECK_HEADER.split('\n', 1)[1]).rstrip('\n').split('\n')
    lines = {}
    for i, b in enumerate(bindings):
        out.append(f'theorem genesis_bind_{i} : {b["spec"]} := {b["proof"]}')
        lines[len(out)] = i
    out.append('#eval show MetaM Unit from do')
    for i, b in enumerate(bindings):
        out.append(f'  genesisBind "GENESIS-{nonce}" {i} `genesis_bind_{i} `{b["spec"]}')
    plain = [m for m in dump if m not in trees]
    out.append(f'  genesisDump "GENESIS-{nonce}" [{", ".join("`" + m for m in plain)}]')
    if trees:
        out.append(f'  genesisDump "GENESIS-{nonce}" [{", ".join("`" + m for m in trees)}] true')
    out.append(f'  IO.println "GENESIS-{nonce} done"')
    return '\n'.join(out) + '\n', lines


def accept(modules, bindings, *, policy=POLICY, cache=None, trees=()):
    """Accept or reject `bindings` ({'spec': Mod.const, 'proof': Mod.const}) over `modules`.

    `modules`: ordered [{'name', 'source', 'trusted'}]. Returns a receipt with per-module
    compile results, per-binding statuses, the declaration table and the environment.

    `cache` (optional, owned by the caller's acceptance session, never by a search) reuses
    compilations keyed by module name, source and the exact bytes of every dependency."""
    try:
        env = _env()
    except (ToolUnavailable, W.WorkspaceUnavailable) as exc:
        return {'status': 'CHECKER_ERROR', 'reason': str(exc), 'bindings': [
            dict(b, status='CHECKER_ERROR') for b in bindings]}
    names = [m['name'] for m in modules]
    if len(set(names)) != len(names) or not all(MODULE_NAME.match(n) for n in names):
        raise ChainError('module names must be distinct single identifiers')
    for b in bindings:
        if not (CONST_NAME.match(b['spec']) and CONST_NAME.match(b['proof'])):
            raise ChainError('binding names must be plain constant names')
    sources = {m['name']: m['source'] for m in modules}
    trusted = {m['name'] for m in modules if m['trusted']}
    for i, m in enumerate(modules):              # chain structure is checked before anything compiles
        if m['trusted']:
            extra = sorted(set(imports_of(m['source'])) - set(env['modules']) - (trusted & set(names[:i])))
            if extra:
                raise ChainError(f'trusted module {m["name"]} imports {extra}')
    base = {'schema': 'genesis-lean-chain-receipt-v1',
            'environment': {k: v for k, v in env.items() if k not in ('modules', 'olean_root', 'toolchain_root')},
            'modules': [], 'bindings': []}
    compiled, failed = {}, {}
    for i, m in enumerate(modules):
        earlier = names[:i]
        allowed = set(env['modules']) | ({n for n in earlier if n in trusted} if m['trusted'] else set(earlier))
        entry = {'name': m['name'], 'trusted': m['trusted'], 'source_sha256': bytes_hash(m['source'].encode())}
        problem = None
        if not m['trusted']:
            problem = prescreen(m['source'], permitted=allowed)
        bad_dep = sorted(_closure(m['name'], sources, set(earlier)) & set(failed))
        if problem:
            entry.update(result=problem[0], reason=problem[1])
        elif bad_dep:
            entry.update(result='NOT_ATTEMPTED', reason=f'imports modules that did not compile: {bad_dep}')
        else:
            deps = {}
            for d in _closure(m['name'], sources, set(earlier)):
                deps.update(compiled[d]['artifacts'])
            key = digest({'name': m['name'], 'source': bytes_hash(m['source'].encode()), 'env': env['workspace'],
                          'deps': {k: bytes_hash(v) for k, v in sorted(deps.items())}})
            r = cache.get(key) if cache is not None else None
            if r is None:
                r = compile_module(m['name'], m['source'], deps, env, policy)
                if cache is not None and r['result'] == 'COMPILED':
                    cache[key] = r
            else:
                entry['cached'] = True
            entry.update(result=r['result'], stats=r['stats'], artifact_sha256=r['artifact_sha256'],
                         log=r['log'] if r['result'] != 'COMPILED' else '')
            if r['result'] == 'COMPILED':
                compiled[m['name']] = r
        if entry['result'] != 'COMPILED':
            failed[m['name']] = entry['result']
            if m['trusted']:
                base['modules'].append(entry)
                return dict(base, status='CHECKER_ERROR', reason=f'trusted module {m["name"]} did not compile',
                            bindings=[dict(b, status='CHECKER_ERROR') for b in bindings])
        base['modules'].append(entry)
    usable = [b for b in bindings if b['proof'].split('.')[0] in compiled and b['spec'].split('.')[0] in compiled]
    nonce = secrets.token_hex(12)
    files = {}
    for r in compiled.values():
        files.update(r['artifacts'])
    imports = [n for n in names if n in compiled]
    untrusted = [n for n in imports if n not in trusted]
    check, bind_lines = _check_source(imports, usable, imports, nonce, trees=[t for t in trees if t in imports])
    script = ('set -u\ncd /work/src\n'
              f'lean -D maxHeartbeats={HEARTBEATS} --root=/work/src GenesisCheck.lean > /work/out/check.log 2>&1\n'
              'echo "check-exit $?" > /work/out/exits.log\n' +
              ''.join(f'leanchecker {u} > /work/out/lc-{u}.log 2>&1; echo "lc {u} $?" >> /work/out/exits.log\n'
                      for u in untrusted))
    receipt, out = _run({**files, 'GenesisCheck.lean': check.encode()}, script, env, policy)
    log = out.get('check.log', b'').decode(errors='replace')
    exits = dict(line.split(' ', 1)[1].rsplit(' ', 1) if line.startswith('lc ') else ('check', line.split()[-1])
                 for line in out.get('exits.log', b'').decode().splitlines() if line.strip())
    base['check_stage'] = dict(_stats(receipt), check_sha256=bytes_hash(check.encode()), exits=exits,
                               log=log[-6000:] if receipt.get('status') != 'SUCCESS' else '')
    tag = f'GENESIS-{nonce} '
    lines = [l[len(tag):] for l in log.splitlines() if l.startswith(tag)]
    if receipt['status'] in ('TIMEOUT', 'OOM', 'CPU_LIMIT', 'OUTPUT_LIMIT') or 'done' not in lines:
        status = 'TIMEOUT' if receipt['status'] in ('TIMEOUT', 'CPU_LIMIT') else 'CHECKER_ERROR'
        return dict(base, status=status, reason='the trusted check stage did not complete',
                    bindings=[dict(b, status=status) for b in bindings])
    binds, decls = {}, []
    for l in lines:
        if l.startswith('bind '):
            _, i, how, *rest = l.split(' ', 3)
            binds.setdefault(int(i), []).append((how, rest[0] if rest else ''))
        elif l.startswith('decl '):
            decls.append(json.loads(l[5:]))
    lc_ok = {u: exits.get(u) == '0' for u in untrusted}
    errored = {bind_lines[int(n)] for n in re.findall(r'(?m)^GenesisCheck\.lean:(\d+):\d+: error', log)
               if int(n) in bind_lines}
    if re.search(r'(?m)^GenesisCheck\.lean:(\d+):\d+: error', log) and not errored:
        return dict(base, status='CHECKER_ERROR', reason='the trusted check file failed outside the bindings',
                    bindings=[dict(b, status='CHECKER_ERROR') for b in bindings])
    for b in bindings:
        mod = b['proof'].split('.')[0]
        out_b = dict(b)
        if b not in usable:
            out_b['status'] = 'NOT_ATTEMPTED' if mod in failed and failed[mod] == 'NOT_ATTEMPTED' else \
                (failed.get(mod) or failed.get(b['spec'].split('.')[0]) or 'ELABORATION_ERROR')
            if out_b['status'] == 'COMPILED':
                out_b['status'] = 'ELABORATION_ERROR'
        else:
            i = usable.index(b)
            got = binds.get(i, [])
            if len(got) != 1 or got[0][0] == 'absent':
                out_b['status'] = 'STATEMENT_MISMATCH'
            else:
                how, axioms_text = got[0]
                axioms = sorted(a.strip() for a in axioms_text.strip().strip('[]').split(',') if a.strip())
                out_b['axioms'] = axioms
                if how != 'exact' or i in errored:
                    out_b['status'] = 'STATEMENT_MISMATCH'
                elif set(axioms) - ALLOWED_AXIOMS:
                    out_b['status'] = 'DISALLOWED_AXIOM'
                    out_b['disallowed'] = sorted(set(axioms) - ALLOWED_AXIOMS)
                elif not lc_ok.get(mod, mod in trusted):
                    out_b['status'] = 'KERNEL_REJECTED'
                else:
                    out_b['status'] = 'CHECKED'
        out_b['outcome_class'] = outcome_class(out_b['status'])
        base['bindings'].append(out_b)
    base['declarations'] = decls
    base['leanchecker'] = lc_ok
    ok = all(b['status'] == 'CHECKED' for b in base['bindings'])
    return dict(base, status='CHECKED' if ok else 'REJECTED')


def type_fingerprint(decl):
    return hashlib.sha256(decl['type'].encode()).hexdigest()


def dependency_closure(declarations, package_modules):
    """Per declaration of the package: the package declarations it depends on
    (transitively) and the workspace modules it touches directly."""
    table = {d['name']: d for d in declarations if d['module'] in package_modules}
    direct = {n: sorted({u for u, mod in d['uses'] if mod in package_modules and u != n}) for n, d in table.items()}
    out = {}
    for n in table:
        seen, stack = set(), list(direct[n])
        while stack:
            x = stack.pop()
            if x in seen or x not in direct:
                continue
            seen.add(x); stack += direct[x]
        out[n] = {'package': sorted(seen),
                  'workspace_modules': sorted({mod for _, mod in table[n]['uses'] if mod not in package_modules})}
    return out


__all__ = ['accept', 'compile_module', 'prescreen', 'outcome_class', 'dependency_closure', 'type_fingerprint',
           'OUTCOME_CLASSES', 'POLICY', 'ChainError']
